17	
18	// memoryNotifyHostedSyncMinInterval throttles the push-hint hosted fact sync
19	// across detached notify processes: a push burst (a rebase + force-push loop)
20	// must not become one sync per push. A minute keeps the trail fresh on the
21	// push beat; the daemon tick remains the reconciliation floor.
22	const memoryNotifyHostedSyncMinInterval = time.Minute
23	
24	// memoryNotifySyncMarkerName is the brain-relative marker recording the last
25	// push-hint sync. Shared by every notify process; read and claimed under the
26	// brain write lock so concurrent hints race safely.
27	const memoryNotifySyncMarkerName = "hosted_sync_notify.json"
28	
29	// notifyHostedFactsSync is a test seam over hostedFactsSyncAndPull.
30	var notifyHostedFactsSync = hostedFactsSyncAndPull
31	
32	// memoryPushWorkLaunch spawns `memory push-work` detached, the same shape as
33	// memoryWorkerLaunch: `memory notify` is a fast content-free hint and must
34	// never carry the upload's network round trips inline — a host adapter may
35	// invoke it synchronously. The child runs with the worker-origin environment
36	// so nothing it shells out to re-notifies. Injectable for tests; a launch
37	// failure never fails the host.
38	var memoryPushWorkLaunch = func(repoDir, branch string) error {
39		args := []string{"memory", "push-work"}
40		if branch != "" {
41			args = append(args, "--branch", branch)
42		}
43		return launchDetachedSelf(repoDir, args...)
44	}
45	
46	// newMemoryPushWorkCommand is the detached half of the push hint: notify
47	// dispatches this verb, and this verb uploads the fact store, throttled.
48	// Hidden — it is an internal dispatch target, not a user surface.
49	func newMemoryPushWorkCommand(opts Options) *cobra.Command {
50		var branch string
51		cmd := &cobra.Command{
52			Use:    "push-work",
53			Hidden: true,
54			Short:  "Upload the memory store for a push hint (internal)",
55			Args:   cobra.NoArgs,
56			RunE: func(cmd *cobra.Command, _ []string) error {
57				// One repo resolution: resolveSessionsBrain would run the same
58				// resolveLocalTargetRepoDir again internally, a redundant git
59				// spawn on every push.
60				repoDir, local, err := base.ResolveLocalTargetRepoDir(cmd.Context(), opts.Runner, agentSurfaceTarget(opts, nil))
61				if err != nil || !local {
62					return nil // no local repo: silence, never an error
63				}
64				storage, err := repoStoragePaths(cmd.Context(), opts.Runner, opts.Env, repoDir)
65				if err != nil {
66					return err
67				}
68				hostedSyncOnPushHint(cmd.Context(), cmd.ErrOrStderr(), opts, repoDir, storage, strings.TrimSpace(branch))
69				return nil
70			},
71		}
72		cmd.Flags().StringVar(&branch, "branch", "", "Captured branch when the host knows it")
73		return cmd
74	}
75	
76	type memoryNotifySyncMarker struct {
77		LastSyncAt time.Time `json:"last_sync_at"`
78	}
79	
80	// hostedSyncOnPushHint uploads the fact store on a push hint: the hinted
81	// branch, then the default branch, throttled by a shared marker. It
82	// deliberately does NOT distill — the hint is an upload beat for facts that
83	// already exist. Fact creation stays on the session-end hook and the daemon
84	// tick until it moves into the memory worker with the session-end deprecation.
85	// The marker is claimed BEFORE the work so concurrent notify processes skip
86	// instead of stampeding; a failed run after the claim simply waits out the
87	// interval, which the never-fails contract already tolerates.
88	//
89	// Same contract as hostedFactsSyncAndPull: this runs behind a host lifecycle
90	// hint, so nothing here may fail the caller — every outcome is reported on
91	// errW and swallowed. The return value says whether the work ran, for tests
92	// and for the caller's log line only.
93	func hostedSyncOnPushHint(ctx context.Context, errW io.Writer, opts Options, repoDir string, storage repoStorage, branch string) bool {
94		// An explicit disconnect must cost nothing per push: bail before claiming
95		// the throttle or spawning sync work. An UNBOUND repo proceeds — the
96		// sync's auto-connect is the designed first-contact path, with its own
97		// gates.
98		if binding, present, err := brainstore.ReadHostedRepoBinding(storage.BrainDir); err == nil && present && binding.OptedOut {
99			return false
100		}
101		claimed := false
102		if err := brainstore.WithBrainWriteLock(storage.BrainDir, func() error {
103			now := opts.Now().UTC()
104			marker := readMemoryNotifySyncMarker(storage.BrainDir)
105			if now.Sub(marker.LastSyncAt) < memoryNotifyHostedSyncMinInterval {
106				return nil
107			}
108			if err := writeMemoryNotifySyncMarker(storage.BrainDir, memoryNotifySyncMarker{LastSyncAt: now}); err != nil {
109				return err
110			}
111			claimed = true
112			return nil
113		}); err != nil {
114			fmt.Fprintf(errW, "memory notify: hosted sync throttle: %v\n", err)
115			return false
116		}
117		if !claimed {
118			return false
119		}
120	
121		if branch == "" {
122			branch = hostedSyncBranch(ctx, opts.Runner, repoDir)
123		}
124		syncBranches := []string{branch}
125		if branch != distillDefaultBranch {
126			syncBranches = append(syncBranches, distillDefaultBranch)
127		}
128		for _, syncBranch := range syncBranches {
129			if _, err := notifyHostedFactsSync(ctx, errW, opts, repoDir, storage, syncBranch); err != nil {
130				fmt.Fprintf(errW, "memory notify: hosted memory sync failed (local brain unaffected): %v\n", err)
131			}
132		}
133		return true
134	}
135	
136	func memoryNotifySyncMarkerPath(brainDir string) string {
137		return filepath.Join(brainDir, memoryNotifySyncMarkerName)
138	}
139	
140	// readMemoryNotifySyncMarker treats a missing or unreadable marker as "never
141	// synced": the worst outcome of a corrupt marker is one extra sync.
142	func readMemoryNotifySyncMarker(brainDir string) memoryNotifySyncMarker {
143		var marker memoryNotifySyncMarker
144		data, err := os.ReadFile(memoryNotifySyncMarkerPath(brainDir))
145		if err != nil {
146			return memoryNotifySyncMarker{}
147		}
148		if err := json.Unmarshal(data, &marker); err != nil {
149			return memoryNotifySyncMarker{}
150		}
151		return marker
152	}
153	
154	func writeMemoryNotifySyncMarker(brainDir string, marker memoryNotifySyncMarker) error {
155		data, err := json.Marshal(marker)
156		if err != nil {
157			return err
158		}
159		return os.WriteFile(memoryNotifySyncMarkerPath(brainDir), data, 0o600)
160	}
