13	// verbatim when set, else the active context's stored login JWT, refreshed if
14	// near expiry. Tokens are expiring JWTs and the daemon's launchd env is baked
15	// at install time, so a token is never persisted or injected — it is minted
16	// per sync and held only in memory. The token is never logged and never echoed
17	// in errors.
18	func mintHostedToken(ctx context.Context, runner CommandRunner, repoDir, entireBinary string) (string, error) {
19		ctx, cancel := context.WithTimeout(ctx, base.HostedShellOutTimeout)
20		defer cancel()
21		stdout, _, err := runner.Run(ctx, repoDir, entireBinary, "auth", "token")
22		if err != nil {
23			return "", fmt.Errorf("mint hosted sync token (`%s auth token`): %w", entireBinary, err)
24		}
25		// The update banner shares stdout with released CLIs; the token is the
26		// last non-empty line.
27		token := ""
28		for _, line := range strings.Split(string(stdout), "\n") {
29			if line = strings.TrimSpace(line); line != "" {
30				token = line
31			}
32		}
33		if token == "" {
34			return "", fmt.Errorf("`%s auth token` printed no token; log in with `%s auth login`", entireBinary, entireBinary)
35		}
36		if !looksLikeJWT(token) {
37			return "", fmt.Errorf("`%s auth token` output does not look like a token; log in with `%s auth login`", entireBinary, entireBinary)
38		}
39		return token, nil
40	}
41	
42	func looksLikeJWT(s string) bool {
43		return strings.Count(s, ".") == 2 && !strings.ContainsAny(s, " \t")
44	}
