149	// runHostedFactsSync is the manual flavor of hostedFactsSyncAndPull: the same
150	// per-fact exchange (batch-upsert this branch's store, pull the repo delta
151	// feed, rebuild the branch store), but the user explicitly asked for this
152	// sync, so failures surface in the exit code and output instead of degrading
153	// to a stderr note (COR-2202 precedent).
154	func runHostedFactsSync(cmd *cobra.Command, opts Options, syncOpts factsSyncOptions, repoDir string, storage repoStorage, branch string) error {
155		ctx := cmd.Context()
156		errW := cmd.ErrOrStderr()
157		target, err := resolveManualHostedTarget(ctx, opts, storage.BrainDir, repoDir, "memories sync", syncOpts.repoID, syncOpts.apiURL, syncOpts.token)
158		if err != nil {
159			return err
160		}
161		srv := &factsync.HTTPServer{BaseURL: target.baseURL, Token: target.token}
162		backendLabel := "hosted (" + strings.TrimRight(target.baseURL, "/") + ")"
163	
164		counts, skipped, pushErr := pushHostedFacts(ctx, storage, srv, target.repoID, branch)
165		if skipped > 0 {
166			fmt.Fprintf(errW, "warning: skipped %d unpublishable record(s) whose content id does not re-derive (kept locally, not uploaded)\n", skipped)
167		}
168		// The pull runs even after a failed push: the team's memories still land,
169		// and the error below reports exactly which half failed.
170		kept, total, manifestErr, pullErr := pullHostedFacts(ctx, opts, repoDir, storage, srv, target.repoID, target.baseURL, target.token, branch)
171		if pushErr == nil && pullErr == nil {
172			// Both halves completed: record the per-branch marker, same rule as the
173			// background sync (the blind-spot note keys off its absence).
174			if err := writeHostedFactsBinding(storage.BrainDir, branch, target.repoID, target.baseURL); err != nil {
175				return fmt.Errorf("memories sync: record hosted target: %w", err)
176			}
177		}
178		if manifestErr != nil {
179			fmt.Fprintf(errW, "warning: memories updated, but the source manifest could not be refreshed: %v\n", manifestErr)
180		}
181		switch {
182		case pushErr != nil && pullErr != nil:
183			return fmt.Errorf("memories sync: push to %s failed: %v; pull failed: %v", backendLabel, pushErr, pullErr)
184		case pushErr != nil:
185			return fmt.Errorf("memories sync: pulled %d memory(ies) from %s (%d kept), but the push failed (local brain unaffected): %w", total, backendLabel, kept, pushErr)
186		case pullErr != nil:
187			return fmt.Errorf("memories sync: pushed %d memory(ies) to %s, but the pull failed (local brain unaffected): %w", counts.Added+counts.Changed+counts.Unchanged, backendLabel, pullErr)
188		}
189	
190		if syncOpts.jsonOut {
191			return cmdutil.WriteJSON(cmd, map[string]any{
192				"branch":                branch,
193				"backend":               backendLabel,
194				"pushed_added":          counts.Added,
195				"pushed_changed":        counts.Changed,
196				"pushed_unchanged":      counts.Unchanged,
197				"skipped_unpublishable": skipped,
198				"feed_facts":            total,
199				"feed_kept":             kept,
200			})
201		}
202		fmt.Fprintf(cmd.OutOrStdout(), "synced %s via %s: pushed added=%d changed=%d unchanged=%d; feed facts=%d kept=%d\n",
203			branch, backendLabel, counts.Added, counts.Changed, counts.Unchanged, total, kept)
204		return nil
205	}
