107	func newHostedFakeServer(t *testing.T, fake *hostedFake) *httptest.Server {
108		t.Helper()
109		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
110			fake.mu.Lock()
111			defer fake.mu.Unlock()
112			fake.requests++
113			w.Header().Set("Content-Type", "application/json")
114			switch {
115			case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/brain/facts"):
116				fake.upsertCalls++
117				if fake.denyPush {
118					w.WriteHeader(http.StatusForbidden)
119					return
120				}
121				records, err := factmerge.ParseNDJSON(r.Body)
122				if err != nil || len(records) == 0 || factmerge.VerifyIdentities(records) != nil {
123					w.WriteHeader(http.StatusBadRequest)
124					return
125				}
126				added, changed := 0, 0
127				for _, rec := range records {
128					if _, ok := fake.index[rec.ID]; ok {
129						changed++
130					} else {
131						added++
132					}
133					fake.put(factsync.FeedItem{Record: rec, CreatedBy: fake.callerBy, CreatedByHandle: fake.callerHandle, UpdatedAt: "2026-10-07T12:00:00.000Z"})
134				}
135				_ = json.NewEncoder(w).Encode(map[string]int{"added": added, "changed": changed, "unchanged": 0})
136			case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/brain/facts"):
137				if fake.denyFeed {
138					w.WriteHeader(http.StatusInternalServerError)
139					return
140				}
141				token := r.URL.Query().Get("pageToken")
142				fake.feedTokens = append(fake.feedTokens, token)
143				if token != "" && fake.rejectTokens > 0 {
144					fake.rejectTokens--
145					w.WriteHeader(http.StatusBadRequest)
146					_, _ = w.Write([]byte(`{"error":"invalid pageToken"}`))
147					return
148				}
149				start := 0
150				if token != "" {
151					n, err := strconv.Atoi(token)
152					if err != nil {
153						w.WriteHeader(http.StatusBadRequest)
154						return
155					}
156					start = n
157				}
158				pageSize, _ := strconv.Atoi(r.URL.Query().Get("pageSize"))
159				if pageSize < 1 || pageSize > 100 {
160					pageSize = 50
161				}
162				end := min(start+pageSize, len(fake.items))
163				var page []factsync.FeedItem
164				if start < end {
165					page = fake.items[start:end]
166				}
167				resp := map[string]any{"items": page, "nextPageToken": nil}
168				if len(page) > 0 {
169					resp["nextPageToken"] = strconv.Itoa(end)
170				}
171				_ = json.NewEncoder(w).Encode(resp)
172			default:
173				w.WriteHeader(http.StatusNotFound)
174			}
175		}))
176		t.Cleanup(srv.Close)
177		return srv
178	}
